<template>
    <div class="page"><div class="page-head"><div><h2>体验项目</h2><p>把真实活动体验转化为可审核、可复盘的用户反馈。</p></div><el-button type="primary" :icon="Plus" @click="reset();dialog=true">新建体验项目</el-button></div>
    <el-alert v-if="error" :title="error" type="error" show-icon closable @close="error=''" />
    <div class="metrics" v-if="data.metrics"><el-card shadow="never"><el-statistic title="开放项目" :value="data.metrics.openProjectCount" /><small>共 {{ data.metrics.projectCount }} 个项目</small></el-card><el-card shadow="never"><el-statistic title="申请人数" :value="data.metrics.applicationCount" /></el-card><el-card shadow="never"><el-statistic title="通过率" :value="data.metrics.approvalRate" suffix="%" /></el-card><el-card shadow="never"><el-statistic title="反馈 / 已采纳" :value="data.metrics.feedbackCount" /><small>已采纳 {{ data.metrics.approvedFeedbackCount }} 条</small></el-card></div>
    <el-card class="panel" shadow="never"><template #header><div class="panel-head"><span>项目与申请</span><el-button text :icon="Refresh" @click="load">刷新</el-button></div></template>
      <el-table :data="data.projects" v-loading="loading" stripe><el-table-column prop="title" label="体验项目" min-width="220"/><el-table-column label="关联活动" min-width="190"><template #default="{row}">{{ row.activity?.title || '未关联' }}</template></el-table-column><el-table-column label="名额"><template #default="{row}">{{ row.approvedCount }}/{{ row.quota || '不限' }}</template></el-table-column><el-table-column label="申请/通过" width="100"><template #default="{row}">{{ row.funnel?.applicationCount || 0 }}/{{ row.funnel?.approvedApplicationCount || 0 }}</template></el-table-column><el-table-column label="通过率" width="90"><template #default="{row}">{{ row.funnel?.approvalRate || 0 }}%</template></el-table-column><el-table-column label="反馈/采纳" width="100"><template #default="{row}">{{ row.funnel?.feedbackCount || 0 }}/{{ row.funnel?.approvedFeedbackCount || 0 }}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status==='open'?'success':row.status==='closed'?'warning':'info'">{{ row.status==='open'?'开放中':row.status==='draft'?'草稿':row.status==='archived'?'已归档':'已关闭' }}</el-tag></template></el-table-column><el-table-column label="操作" width="260"><template #default="{row}"><el-button v-if="row.activity" link type="success" @click="openFunnel(row)">看活动漏斗</el-button><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button v-if="row.status==='draft'||row.status==='closed'" link type="success" @click="changeStatus(row,'open')">开放</el-button><el-button v-if="row.status==='open'" link type="warning" @click="changeStatus(row,'closed')">关闭</el-button></template></el-table-column></el-table>
    </el-card>
    <el-card class="panel" shadow="never"><template #header><div class="panel-head"><span>体验申请（{{ data.applications.length }}）</span></div></template><el-table :data="data.applications" stripe><el-table-column prop="project.title" label="项目" min-width="180"/><el-table-column label="用户"><template #default="{row}">{{ row.user?.nickname || '用户' }} <small>{{ row.user?.maskedPhone || '-' }}</small></template></el-table-column><el-table-column prop="reason" label="申请说明" min-width="220" show-overflow-tooltip/><el-table-column label="状态"><template #default="{row}"><el-tag>{{ statusText(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button v-if="row.status==='pending'" link type="success" @click="review(row,'approved')">通过</el-button><el-button v-if="row.status==='pending'" link type="danger" @click="review(row,'rejected')">拒绝</el-button></template></el-table-column></el-table></el-card>
    <el-card class="panel" shadow="never"><template #header><div class="panel-head"><span>体验反馈（{{ feedbacks.length }}）</span><el-button text :icon="Refresh" @click="load">刷新</el-button></div></template><el-table :data="feedbacks" stripe><el-table-column prop="project.title" label="项目" min-width="180"/><el-table-column prop="rating" label="评分" width="80"/><el-table-column prop="content" label="反馈内容" min-width="300" show-overflow-tooltip/><el-table-column label="状态"><template #default="{row}"><el-tag>{{ statusText(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button v-if="row.status==='pending'" link type="success" @click="reviewFeedback(row,'approved')">采纳</el-button><el-button v-if="row.status==='pending'" link type="danger" @click="reviewFeedback(row,'rejected')">退回</el-button></template></el-table-column></el-table></el-card>
    <el-dialog v-model="dialog" :title="editingId ? '编辑体验项目' : '新建体验项目'" width="560px"><el-form label-position="top"><el-form-item label="项目名称"><el-input v-model="form.title" maxlength="160" /></el-form-item><el-form-item label="关联活动"><el-select v-model="form.activityId" clearable filterable placeholder="可选，建议关联真实活动" style="width:100%"><el-option v-for="item in data.activities" :key="item.id" :label="item.title" :value="item.id" /></el-select></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="4" /></el-form-item><el-form-item label="名额（0 为不限）"><el-input-number v-model="form.quota" :min="0" /></el-form-item><el-form-item label="发布状态"><el-select v-model="form.status"><el-option label="草稿" value="draft"/><el-option label="开放中" value="open"/><el-option label="已关闭" value="closed"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import {Plus,Refresh} from '@element-plus/icons-vue';import {api} from '../api';const router=useRouter();const loading=ref(false),saving=ref(false),dialog=ref(false),error=ref(''),feedbacks=ref<any[]>([]),editingId=ref(0),data=reactive<any>({metrics:null,projects:[],applications:[],activities:[]}),form=reactive({title:'',description:'',quota:0,status:'draft',activityId:null as number|null});const statusText=(v:string)=>({pending:'待审核',approved:'已通过',rejected:'已拒绝',feedback_submitted:'已反馈'} as any)[v]||v;async function load(){loading.value=true;error.value='';try{const result=await api.get<any,any>('/admin/experiences');data.metrics=result.metrics||null;data.projects=result.projects||[];data.applications=result.applications||[];data.activities=result.activities||[];feedbacks.value=await api.get<any,any[]>('/admin/experiences/feedback')}catch(e){const issue=e as any;error.value=issue?.message||'体验数据加载失败'}finally{loading.value=false}}function openFunnel(row:any){if(row.activity?.id)router.push({path:'/funnels',query:{activityId:String(row.activity.id)}})}function reset(){editingId.value=0;form.title='';form.description='';form.quota=0;form.status='draft';form.activityId=null}function edit(row:any){editingId.value=row.id;form.title=row.title;form.description=row.description||'';form.quota=row.quota||0;form.status=row.status==='archived'?'closed':row.status;form.activityId=row.activity?.id||null;dialog.value=true}async function save(){if(!form.title.trim()){ElMessage.warning('请填写项目名称');return}saving.value=true;try{const payload={title:form.title.trim(),description:form.description.trim(),quota:Number(form.quota)||0,status:form.status,activityId:form.activityId||null};if(editingId.value)await api.patch(`/admin/experiences/${editingId.value}`,payload);else await api.post('/admin/experiences',payload);ElMessage.success('体验项目已保存');dialog.value=false;reset();await load()}catch(e){const issue=e as any;ElMessage.error(issue?.message||'保存失败')}finally{saving.value=false}}async function changeStatus(row:any,status:string){try{await ElMessageBox.confirm(status==='open'?'开放后用户可以提交体验申请，确认继续？':'关闭后不会再接受新的申请，确认继续？','更新项目状态',{type:status==='open'?'info':'warning'});await api.patch(`/admin/experiences/${row.id}`,{status});ElMessage.success('项目状态已更新');await load()}catch(e){const issue=e as any;if(e!=='cancel'&&e!=='close')ElMessage.error(issue?.message||'状态更新失败')}}async function review(row:any,status:string){try{await ElMessageBox.confirm(status==='approved'?'通过后会占用体验名额，确认继续？':'确认拒绝该申请？','审核申请',{type:status==='approved'?'info':'warning'});await api.patch(`/admin/experiences/applications/${row.id}/review`,{status});ElMessage.success('申请状态已更新');await load()}catch(e){const issue=e as any;if(e!=='cancel'&&e!=='close'){ElMessage.error(issue?.message||'审核失败')}}}async function reviewFeedback(row:any,status:string){try{await api.patch(`/admin/experiences/feedback/${row.id}/review`,{status});ElMessage.success('体验反馈状态已更新');await load()}catch(e){const issue=e as any;ElMessage.error(issue?.message||'审核失败')}};onMounted(load);</script>
<style scoped>.page{padding:24px;background:var(--el-bg-color-page);min-height:100%}.page-head{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:18px}.page-head h2{margin:0;font-size:24px}.page-head p{margin:8px 0 0;color:var(--el-text-color-secondary)}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.metrics .el-card{min-height:104px}.metrics small{display:block;color:var(--el-text-color-secondary);margin-top:8px}.panel{margin-top:18px}.panel-head{display:flex;justify-content:space-between;align-items:center;font-weight:700}.panel small{color:var(--el-text-color-secondary);margin-left:8px}@media (max-width:900px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media (max-width:560px){.page{padding:16px}.page-head{gap:12px}.page-head h2{font-size:20px}.metrics{grid-template-columns:1fr}}</style>
